"""Professional batch-scoring prototype. Requires artifacts generated by train.py."""
import hashlib
from io import BytesIO
import json
import logging
from pathlib import Path
import importlib.metadata

import joblib
import numpy as np
import pandas as pd
import streamlit as st

from aps_pipeline import validate_raw
from train import cost_row

st.set_page_config(page_title="APS | Fleet review", layout="wide")
ARTIFACTS = Path(__file__).resolve().parent / "artifacts"


@st.cache_resource
def load_release(release_path, fingerprint):
    root = Path(release_path)
    meta = json.loads((root / "metadata.json").read_text(encoding="utf-8"))
    for package, version in meta["versions"].items():
        if importlib.metadata.version(package) != version:
            raise ValueError(f"{package} differs from the training environment.")
    raw = (root / "aps_pipeline.joblib").read_bytes()
    if hashlib.sha256(raw).hexdigest() != meta["model_sha256"]:
        raise ValueError("Model checksum does not match release metadata.")
    # Load only your own trusted deployment artifact, never an uploaded pickle.
    return joblib.load(BytesIO(raw)), meta


try:
    fingerprint = (ARTIFACTS / "metadata.json").read_bytes()
    model, meta = load_release(str(ARTIFACTS), fingerprint)
except Exception:
    logging.exception("Release loading failed")
    st.error("Model release unavailable. Ask the administrator to check the deployment logs.")
    st.stop()

with st.sidebar:
    st.title("APS")
    st.caption("Fleet inspection support")
    page = st.radio("Workspace", ["Fleet review", "Policy analysis", "Model record"])
    st.divider()
    st.caption(f"Release: {meta['model_id']}")
    st.caption(f"Decision threshold: {meta['threshold']:.3f}")
    st.caption("Research prototype · independent Scania dataset study")

if page == "Fleet review":
    st.title("Fleet review")
    st.caption("Upload sensor records, review inspection flags, and export the queue.")
    st.info("Scores indicate evidence for APS-related failure. A low score does not certify vehicle health.")
    st.download_button("Download CSV header template",
                       pd.DataFrame(columns=meta["raw_features"]).to_csv(index=False),
                       "aps_input_template.csv", "text/csv")
    upload = st.file_uploader("Sensor CSV · 170 raw feature columns", type=["csv"])
    st.caption("Plain CSV with one header row. Optional record_id column; use blank or 'na' for missing readings. Maximum 10 MB / 10,000 rows.")
    if upload is None:
        st.stop()
    payload = upload.getvalue()
    if len(payload) > 10 * 1024 * 1024:
        st.error("File exceeds 10 MB.")
        st.stop()
    try:
        frame = pd.read_csv(BytesIO(payload), na_values="na", nrows=10001)
        if len(frame) > 10000:
            raise ValueError("At most 10,000 records per batch.")
        ids = (frame.pop("record_id") if "record_id" in frame else
               pd.Series([f"row-{i+1}" for i in range(len(frame))]))
        if ids.isna().any() or not ids.is_unique:
            raise ValueError("record_id must be present and unique for every record.")
        raw = validate_raw(frame, meta["raw_features"])
    except (ValueError, pd.errors.ParserError, UnicodeError) as exc:
        st.error(str(exc))
        st.stop()
    batch_id = hashlib.sha256(payload).hexdigest()
    cache_key = (batch_id, meta["model_sha256"])
    # Per-session cache avoids sharing uploaded records across users.
    if st.session_state.get("batch_key") != cache_key:
        with st.spinner("Scoring records…"):
            try:
                pos = int(np.flatnonzero(model.classes_ == 1)[0])
                scores = model.predict_proba(raw)[:, pos]
            except Exception:
                logging.exception("Batch scoring failed")
                st.error("Scoring failed. Ask the administrator to check deployment logs.")
                st.stop()
        st.session_state["batch_scores"] = scores
        st.session_state["batch_key"] = cache_key
    scores = st.session_state["batch_scores"]
    result = pd.DataFrame({"record_id": ids.astype(str).to_numpy(), "model_score": scores,
                           "missing_fraction": raw.isna().mean(axis=1).to_numpy()})
    result["action"] = np.where(scores >= meta["threshold"], "Review for inspection", "Below threshold")
    result["model_id"] = meta["model_id"]
    result["threshold"] = meta["threshold"]
    a, b, c = st.columns(3)
    a.metric("Records", len(result))
    b.metric("Flagged for review", int((scores >= meta["threshold"]).sum()))
    c.metric("Median missing sensors", f"{result.missing_fraction.median():.1%}")
    view = st.radio("Queue", ["All", "Flagged"], horizontal=True)
    shown = result if view == "All" else result[result.action == "Review for inspection"]
    shown = shown.sort_values("model_score", ascending=False)
    st.dataframe(shown, hide_index=True, use_container_width=True)
    st.download_button("Export current queue", shown.to_csv(index=False), "aps_review_queue.csv", "text/csv")
    st.subheader("Record details")
    selected = st.selectbox("Record", result.record_id.tolist())
    row_index = result.index[result.record_id == selected][0]
    st.caption("Raw anonymized sensor readings. Sensor names do not establish a mechanical diagnosis.")
    st.dataframe(raw.iloc[row_index].rename("reading").to_frame(), use_container_width=True)

elif page == "Policy analysis":
    st.title("Policy analysis")
    st.caption("Validation data only. Sandbox changes do not alter the deployed decision threshold.")
    try:
        evidence = pd.read_csv(ARTIFACTS / "validation_predictions.csv")
    except (OSError, ValueError):
        st.error("Validation evidence is unavailable.")
        st.stop()
    t = st.slider("Scenario threshold", 0.0, 1.0, min(1.0, float(meta["threshold"])), 0.01)
    current = cost_row(evidence.label, evidence.score, t)
    a, b, c = st.columns(3)
    a.metric("False positives", current["fp"])
    b.metric("False negatives", current["fn"])
    c.metric("Validation cost units", f"{current['cost']:,}")
    curve = pd.DataFrame([cost_row(evidence.label, evidence.score, x)
                          for x in np.linspace(0, 1, 101)])
    st.line_chart(curve.set_index("threshold")[["cost"]])
    st.caption("Benchmark loss = 10 × false positives + 500 × false negatives. These are scenario costs, not measured annual savings.")
    st.caption(f"Frozen release threshold: {meta['threshold']:.3f}. Scores have not undergone probability calibration.")

else:
    st.title("Model record")
    st.caption(f"Built {meta['created_utc']} · model {meta['model_id']}")
    metrics = pd.DataFrame(meta["metrics"]).T
    st.dataframe(metrics, use_container_width=True)
    st.write("The full preprocessing pipeline was fitted on the fit partition. The operating threshold was selected on a separate stratified validation partition. The official test was evaluated after freezing the policy.")
    st.write("Scope: APS-related versus non-APS-related failure classification. This dataset does not validate breakdown timing, remaining useful life, component replacement, or dispatch safety.")
    with st.expander("Release provenance"):
        st.json({k: v for k, v in meta.items() if k != "metrics"})
